// Conversions and revenue from Meta's actions arrays, for the action type you track
const ACTIONS = {
  purchase: ['omni_purchase', 'purchase', 'offsite_conversion.fb_pixel_purchase', 'onsite_web_purchase'],
  lead: ['lead', 'onsite_conversion.lead_grouped', 'offsite_conversion.fb_pixel_lead', 'onsite_web_lead'],
  complete_registration: ['complete_registration', 'offsite_conversion.fb_pixel_complete_registration'],
  messaging: ['onsite_conversion.messaging_conversation_started_7d'],
};
function pick(list, types) { for (const t of types) { const a = (list || []).find(x => x.action_type === t); if (a) return Number(a.value) || 0; } return 0; }
function kpis(r, conv) {
  const types = ACTIONS[conv] || [conv];
  const spend = Number(r.spend) || 0, impressions = Number(r.impressions) || 0, clicks = Number(r.inline_link_clicks || r.clicks) || 0;
  const conversions = pick(r.actions, types), revenue = pick(r.action_values, types);
  return { name: r.campaign_name || r.ad_name || 'Total', id: r.campaign_id || r.ad_id || '', spend, impressions, clicks,
    reach: Number(r.reach) || 0, frequency: Number(r.frequency) || (r.reach ? impressions / r.reach : 0),
    ctr: impressions ? clicks / impressions * 100 : 0, cpc: clicks ? spend / clicks : 0, cpm: impressions ? spend / impressions * 1000 : 0,
    conversions, revenue, cpa: conversions ? spend / conversions : null, roas: spend && revenue ? revenue / spend : null };
}
function total(rows) {
  const t = rows.reduce((a, r) => ({ spend: a.spend + r.spend, impressions: a.impressions + r.impressions, clicks: a.clicks + r.clicks,
    reach: a.reach + r.reach, conversions: a.conversions + r.conversions, revenue: a.revenue + r.revenue }),
    { spend: 0, impressions: 0, clicks: 0, reach: 0, conversions: 0, revenue: 0 });
  return { ...t, ctr: t.impressions ? t.clicks / t.impressions * 100 : 0, cpc: t.clicks ? t.spend / t.clicks : 0,
    cpm: t.impressions ? t.spend / t.impressions * 1000 : 0, cpa: t.conversions ? t.spend / t.conversions : null, roas: t.spend && t.revenue ? t.revenue / t.spend : null };
}
const pct = (a, b) => (a === null || b === null || !b) ? null : Math.round((a - b) / b * 100);

// Week over week per campaign, account totals and rule-based flags
function compare(cfg, curRows, prevRows) {
  const conv = cfg.conversion_action || 'purchase';
  const cur = (curRows || []).map(r => kpis(r, conv)).filter(r => r.spend > 0 || r.impressions > 0);
  const prevMap = Object.fromEntries((prevRows || []).map(r => kpis(r, conv)).map(r => [r.id, r]));
  const T = total(cur), P = total(Object.values(prevMap));
  const tCpa = Number(cfg.target_cpa) || 0, tRoas = Number(cfg.target_roas) || 0;
  const flags = [], wins = [];
  for (const c of cur) {
    const p = prevMap[c.id];
    c.spend_change = p ? pct(c.spend, p.spend) : null; c.cpa_change = p ? pct(c.cpa, p.cpa) : null; c.conv_change = p ? pct(c.conversions, p.conversions) : null;
    if (c.spend >= Math.max(20, tCpa) && c.conversions === 0) flags.push(`${c.name}: spent ${c.spend.toFixed(2)} with no ${conv}s`);
    if (tCpa && c.cpa && c.cpa > tCpa * 1.3) flags.push(`${c.name}: CPA ${c.cpa.toFixed(2)} is ${Math.round((c.cpa / tCpa - 1) * 100)}% above target ${tCpa}`);
    if (tRoas && c.roas !== null && c.roas < tRoas * 0.7 && c.spend > 20) flags.push(`${c.name}: ROAS ${c.roas.toFixed(2)} vs target ${tRoas}`);
    if (c.impressions > 1000 && c.ctr < Number(cfg.min_ctr || 0.8)) flags.push(`${c.name}: link CTR ${c.ctr.toFixed(2)}% is low`);
    if (c.frequency > Number(cfg.max_frequency || 3)) flags.push(`${c.name}: frequency ${c.frequency.toFixed(1)} (ad fatigue risk)`);
    if (c.cpa_change !== null && c.cpa_change <= -15 && c.conversions >= 3) wins.push(`${c.name}: CPA down ${-c.cpa_change}% to ${c.cpa.toFixed(2)}`);
    if (tRoas && c.roas !== null && c.roas >= tRoas && c.spend > 20) wins.push(`${c.name}: ROAS ${c.roas.toFixed(2)} beats target`);
  }
  cur.sort((a, b) => b.spend - a.spend);
  const d = { spend: pct(T.spend, P.spend), conversions: pct(T.conversions, P.conversions), cpa: pct(T.cpa, P.cpa), roas: pct(T.roas, P.roas), ctr: pct(T.ctr, P.ctr) };
  const f = n => n === null || n === undefined ? 'n/a' : Number(n).toFixed(2);
  const ch = v => v === null ? '' : ` (${v >= 0 ? '+' : ''}${v}% WoW)`;
  const facts = `Account ${cfg.client_name || cfg.ad_account_id}, ${cfg.period}. Conversion = ${conv}. ` +
    `Totals: spend ${f(T.spend)}${ch(d.spend)}, ${T.conversions} conversions${ch(d.conversions)}, CPA ${f(T.cpa)}${ch(d.cpa)}, ROAS ${f(T.roas)}${ch(d.roas)}, link CTR ${f(T.ctr)}%${ch(d.ctr)}. ` +
    `Targets: CPA ${tCpa || 'none'}, ROAS ${tRoas || 'none'}. Campaigns: ` +
    cur.slice(0, 15).map(c => `${c.name} spend ${f(c.spend)}${ch(c.spend_change)}, conv ${c.conversions}, CPA ${f(c.cpa)}, ROAS ${f(c.roas)}, CTR ${f(c.ctr)}%, freq ${f(c.frequency)}`).join('; ') +
    `. Rule flags: ${flags.join('; ') || 'none'}. Wins: ${wins.join('; ') || 'none'}.`;
  return { totals: T, previous: P, deltas: d, campaigns: cur, flags, wins, facts, has_data: cur.length > 0 };
}

const cfg = { ...$('Set report settings').first().json, period: `${$today.minus({ days: 7 }).toFormat('d LLL')} - ${$today.minus({ days: 1 }).toFormat('d LLL yyyy')}` };
const res = compare(cfg, $('Get last week by campaign').first().json.data, $('Get the week before').first().json.data);
return [{ json: { ...cfg, ...res } }];

