const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// HTML report: KPI tiles with week-over-week change, AI notes and a campaign table
const r = $('Compare weeks and flag campaigns').item.json;
const ai = $json.output || {};
const cur = r.currency || '';
const money = n => n === null || n === undefined ? '-' : `${cur}${Number(n).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
const delta = (v, goodUp = true) => v === null || v === undefined ? '' : `<br><small style="color:${(v >= 0) === goodUp ? '#1a7f37' : '#c62828'}">${v >= 0 ? '+' : ''}${v}% vs last week</small>`;
const tile = (label, val, d) => `<td style="padding:10px;border:1px solid #eee;text-align:center"><small>${label}</small><br><b style="font-size:18px">${val}</b>${d}</td>`;
const T = r.totals, D = r.deltas;
const tiles = `<table style="border-collapse:collapse"><tr>${tile('Spend', money(T.spend), delta(D.spend, true))}${tile('Conversions', T.conversions, delta(D.conversions, true))}` +
  `${tile('CPA', money(T.cpa), delta(D.cpa, false))}${tile('ROAS', T.roas === null ? '-' : T.roas.toFixed(2), delta(D.roas, true))}${tile('Link CTR', T.ctr.toFixed(2) + '%', delta(D.ctr, true))}</tr></table>`;
const li = a => (a || []).map(x => `<li>${esc(x)}</li>`).join('');
const rows = r.campaigns.slice(0, 15).map(c => `<tr><td>${esc(c.name)}</td><td align="right">${money(c.spend)}</td><td align="right">${c.conversions}</td><td align="right">${money(c.cpa)}</td><td align="right">${c.roas === null ? '-' : c.roas.toFixed(2)}</td><td align="right">${c.ctr.toFixed(2)}%</td><td align="right">${c.frequency.toFixed(1)}</td></tr>`).join('');
const html = `<h2>Meta Ads weekly report${r.client_name ? ': ' + esc(r.client_name) : ''}</h2><p>${esc(r.period)}</p>
<p style="font-size:16px"><b>${esc(ai.headline || '')}</b></p>${tiles}
<h3>What worked</h3><ul>${li(ai.wins)}</ul><h3>What needs attention</h3><ul>${li(ai.problems)}</ul><h3>Next steps</h3><ol>${li(ai.actions)}</ol>
<h3>Campaigns</h3><table cellpadding="5" style="border-collapse:collapse;font-size:13px"><tr><th align="left">Campaign</th><th>Spend</th><th>Conv.</th><th>CPA</th><th>ROAS</th><th>CTR</th><th>Freq.</th></tr>${rows}</table>
<p><small>Conversions = ${esc(r.conversion_action)}. Data from the Meta Marketing API; recent days can still change slightly.</small></p>`;
return { json: { ...r, html, subject: `Meta Ads: ${money(T.spend)} spent, ${T.conversions} ${r.conversion_action}s, CPA ${money(T.cpa)} (${r.period})` } };
